/** Earth-only, equinox-anchored Kepler experiment. Fixed a=1 au, year=365 model days. */
export interface OrbitParameters {
  eccentricity: number;
  /** Inertial longitude of the apparent Sun at perihelion (degrees). */
  perihelion: number;
  /** Static azimuth of the tilted axis, NOT a time-dependent precession simulation. */
  axis: number;
}
export const CLASSIC_ORBIT: Readonly<OrbitParameters> = Object.freeze({eccentricity:0,perihelion:0,axis:0});
export const MAX_ECCENTRICITY = 0.3;
const TAU=2*Math.PI, DEG=Math.PI/180;
export function wrapDegrees(angle:number):number {
  if(!Number.isFinite(angle))throw new RangeError('Orbital angle must be finite.');
  return ((angle%360)+360)%360;
}
export function normalizeOrbit(orbit:OrbitParameters=CLASSIC_ORBIT):OrbitParameters {
  if(!Number.isFinite(orbit.eccentricity)||orbit.eccentricity<0||orbit.eccentricity>MAX_ECCENTRICITY)
    throw new RangeError('Eccentricity must be between 0 and 0.3.');
  return {eccentricity:orbit.eccentricity,perihelion:wrapDegrees(orbit.perihelion),axis:wrapDegrees(orbit.axis)};
}
export function orbitKey(orbit:OrbitParameters=CLASSIC_ORBIT):string {
  const o=normalizeOrbit(orbit);
  // A circle has no physically distinct perihelion. Keep its UI setting, not a false cache distinction.
  return `${o.eccentricity}:${o.eccentricity===0?0:o.perihelion}:${o.axis}`;
}
export function isClassicOrbit(orbit:OrbitParameters=CLASSIC_ORBIT):boolean {return orbitKey(orbit)==='0:0:0';}

/** Unique elliptical solution on [-pi,pi]. Newton is bounded and bracketed, never open-ended. */
export function solveKepler(meanAnomaly:number,eccentricity:number):number {
  if(!Number.isFinite(meanAnomaly)||!Number.isFinite(eccentricity)||eccentricity<0||eccentricity>=1)
    throw new RangeError('Kepler inputs must be finite, with 0 <= e < 1.');
  const m=((meanAnomaly+Math.PI)%TAU+TAU)%TAU-Math.PI;
  if(eccentricity===0)return m;
  let lo=-Math.PI,hi=Math.PI,e=m;
  for(let iteration=0;iteration<64;iteration++){
    const residual=e-eccentricity*Math.sin(e)-m;
    if(Math.abs(residual)<2e-14)return e;
    if(residual>0)hi=e;else lo=e;
    const proposed=e-residual/(1-eccentricity*Math.cos(e));
    e=proposed>lo&&proposed<hi?proposed:(lo+hi)/2;
  }
  throw new Error('Kepler equation did not converge.');
}
function meanAtTrueAnomaly(anomaly:number,e:number):number {
  const E=Math.atan2(Math.sqrt(1-e*e)*Math.sin(anomaly),e+Math.cos(anomaly));
  return E-e*Math.sin(E);
}
export interface OrbitalMoment {
  solarLongitude: number;
  seasonalLongitude: number;
  distanceAU: number;
  irradianceFactor: number;
  /** v / speed of the same-a circular orbit. */
  speedRatio: number;
  /** d(true anomaly)/dt divided by mean motion. */
  angularRateRatio: number;
  eccentricAnomaly: number;
  meanAnomaly: number;
}
/** March-reference equinox stays at model day80 for each configuration, as in the classic lab. */
export function orbitalMoment(day:number,orbit:OrbitParameters=CLASSIC_ORBIT):OrbitalMoment {
  if(!Number.isFinite(day))throw new RangeError('Model day must be finite.');
  const o=normalizeOrbit(orbit),e=o.eccentricity,axis=o.axis*DEG,p=o.perihelion*DEG;
  const phase=(2*Math.PI*(day-80))/365;
  if(e===0)return {solarLongitude:phase+axis,seasonalLongitude:phase,distanceAU:1,irradianceFactor:1,
    speedRatio:1,angularRateRatio:1,eccentricAnomaly:phase,meanAnomaly:phase};
  const m0=meanAtTrueAnomaly(axis-p,e),meanAnomaly=m0+phase;
  const E=solveKepler(meanAnomaly,e),r=1-e*Math.cos(E);
  const nu=Math.atan2(Math.sqrt(1-e*e)*Math.sin(E),Math.cos(E)-e),lambda=nu+p;
  return {solarLongitude:lambda,seasonalLongitude:lambda-axis,distanceAU:r,irradianceFactor:1/(r*r),
    speedRatio:Math.sqrt(2/r-1),angularRateRatio:Math.sqrt(1-e*e)/(r*r),eccentricAnomaly:E,meanAnomaly};
}
/** Invert the calendar for a seasonal longitude: 0/90/180/270 = the four reference positions. */
export function dayAtSeasonalLongitude(degrees:number,orbit:OrbitParameters=CLASSIC_ORBIT):number {
  const o=normalizeOrbit(orbit),theta=wrapDegrees(degrees)*DEG;
  if(o.eccentricity===0)return ((80+365*theta/TAU-1)%365+365)%365+1;
  const relative=(o.axis-o.perihelion)*DEG;
  const delta=meanAtTrueAnomaly(relative+theta,o.eccentricity)-meanAtTrueAnomaly(relative,o.eccentricity);
  return ((80+365*delta/TAU-1)%365+365)%365+1;
}
export function perihelionDay(orbit:OrbitParameters=CLASSIC_ORBIT):number|null {
  const o=normalizeOrbit(orbit);return o.eccentricity===0?null:dayAtSeasonalLongitude(o.perihelion-o.axis,o);
}
export function maximumSolarFactor(orbit:OrbitParameters=CLASSIC_ORBIT):number {
  const e=normalizeOrbit(orbit).eccentricity;return 1/((1-e)*(1-e));
}

solar.source:
import { orbitalMoment, isClassicOrbit, dayAtSeasonalLongitude, type OrbitParameters } from './orbit';
export const SOLAR_CONSTANT = 1361;

const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function degToRad(value: number): number {
  return value * DEG;
}

export function radToDeg(value: number): number {
  return value * RAD;
}

export function orbitalLongitudeRad(dayOfYear: number, orbit?: OrbitParameters): number {
  // Inertial solar longitude; optional Kepler geometry, spring reference anchored at day 80.
  return orbitalMoment(dayOfYear, orbit).solarLongitude;
}

export function solarDeclinationDeg(dayOfYear: number, obliquityDeg: number, orbit?: OrbitParameters): number {
  const epsilon = degToRad(obliquityDeg);
  const lambda = orbitalMoment(dayOfYear, orbit).seasonalLongitude;
  return radToDeg(Math.asin(clamp(Math.sin(epsilon) * Math.sin(lambda), -1, 1)));
}

export function sunsetHourAngleRad(latitudeDeg: number, declinationDeg: number): number {
  const phi = degToRad(latitudeDeg);
  const delta = degToRad(declinationDeg);
  const a = Math.sin(phi) * Math.sin(delta);
  const b = Math.cos(phi) * Math.cos(delta);
  // cos(zenith) = a + b*cos(hour angle); no singular tangents at either pole.
  // At an exact all-day horizon (a=b=0), 12 h is a reporting convention.
  // Incoming energy is zero there; it is not 12 hours of effective sunlight.
  if (Math.abs(b) < 1e-12) {
    if (a > 1e-12) return Math.PI;
    if (a < -1e-12) return 0;
    return Math.PI / 2;
  }
  const x = -a / b;

  if (x <= -1) return Math.PI;
  if (x >= 1) return 0;
  return Math.acos(x);
}

export function dayLengthHours(
  latitudeDeg: number,
  dayOfYear: number,
  obliquityDeg: number,
  orbit?: OrbitParameters,
): number {
  const declination = solarDeclinationDeg(dayOfYear, obliquityDeg, orbit);
  const hourAngle = sunsetHourAngleRad(latitudeDeg, declination);
  return clamp((24 * hourAngle) / Math.PI, 0, 24);
}

export function dailyMeanInsolation(
  latitudeDeg: number,
  dayOfYear: number,
  obliquityDeg: number,
  orbit?: OrbitParameters,
): number {
  const phi = degToRad(latitudeDeg);
  const delta = degToRad(solarDeclinationDeg(dayOfYear, obliquityDeg, orbit));
  const h0 = sunsetHourAngleRad(latitudeDeg, radToDeg(delta));

  const q =
    (solarIrradiance(dayOfYear, orbit) / Math.PI) *
    (h0 * Math.sin(phi) * Math.sin(delta) +
      Math.cos(phi) * Math.cos(delta) * Math.sin(h0));

  return Math.max(0, q);
}

export function subsolarLatitudeDeg(dayOfYear: number, obliquityDeg: number, orbit?: OrbitParameters): number {
  return solarDeclinationDeg(dayOfYear, obliquityDeg, orbit);
}

export function seasonLabel(dayOfYear: number, orbit?: OrbitParameters): string {
  const anchors = [
    { day: dayAtSeasonalLongitude(0, orbit), label: 'Near March equinox (model)' },
    { day: dayAtSeasonalLongitude(90, orbit), label: 'Near June solstice (model)' },
    { day: dayAtSeasonalLongitude(180, orbit), label: 'Near September equinox (model)' },
    { day: dayAtSeasonalLongitude(270, orbit), label: 'Near December solstice (model)' },
  ];

  let best = anchors[0];
  let bestDistance = 999;
  for (const anchor of anchors) {
    const direct = Math.abs(dayOfYear - anchor.day);
    const wrapped = Math.min(direct, 365 - direct);
    if (wrapped < bestDistance) {
      bestDistance = wrapped;
      best = anchor;
    }
  }

  if (bestDistance <= 5) return isClassicOrbit(orbit) ? best.label : ['Spring reference','Northern summer reference','Autumn reference','Northern winter reference'][anchors.indexOf(best)];

  const monthStarts = [1, 32, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  let month = 0;
  for (let i = 0; i < monthStarts.length; i += 1) {
    if (dayOfYear >= monthStarts[i]) month = i;
  }
  return months[month];
}

/** Incoming ray-normal TOA flux; S0 is specified at 1 au, not renormalized per year. */
export function solarIrradiance(day:number, orbit?:OrbitParameters):number {
  return SOLAR_CONSTANT * orbitalMoment(day,orbit).irradianceFactor;
}

climateGeography.source:
export type ClimateProfile = 'classic' | 'idealized-land' | 'idealized-ocean';

export const CLIMATE_PROFILES = Object.freeze({
  classic: { effectiveDepth: null, counterpart: null },
  'idealized-land': { effectiveDepth: 2.5, counterpart: 'idealized-ocean' },
  'idealized-ocean': { effectiveDepth: 50, counterpart: 'idealized-land' },
} satisfies Record<ClimateProfile, {
  effectiveDepth: number | null;
  counterpart: ClimateProfile | null;
}>);

export function effectiveHeatDepth(profile: ClimateProfile, classicDepth: number): number {
  return CLIMATE_PROFILES[profile].effectiveDepth ?? classicDepth;
}

export function geographyCounterpart(profile: ClimateProfile): ClimateProfile | null {
  return CLIMATE_PROFILES[profile].counterpart;
}

export function isIdealizedGeography(profile: ClimateProfile): boolean {
  return profile !== 'classic';
}

export function climateProfileKey(profile: ClimateProfile, classicDepth: number): string {
  // Keep the retained Classic control in provenance even when an idealized
  // profile uses a fixed effective depth. Portable state can change it while
  // the material remains selected, and ThermalSolution.depth owns that value.
  return `${profile}:retained-${classicDepth}:effective-${effectiveHeatDepth(profile, classicDepth)}`;
}
